export default "using System.Linq;\r\nusing System.Collections;\r\nusing System.Collections.Generic;\r\nusing UnityEngine;\r\nusing UnityEngine.UI;\r\nusing UnityEngine.SceneManagement;\r\nusing TMPro;\r\n\r\npublic static class ES3 {\r\n    public static bool LoadBool(string key, bool defaultValue) {\r\n        return PlayerPrefs.GetInt(key, defaultValue ? 1 : 0) == 1;\r\n    }\r\n    public static int LoadInt(string key, int defaultValue) {\r\n        return PlayerPrefs.GetInt(key, defaultValue);\r\n    }\r\n    public static void SaveBool(string key, bool value) {\r\n        PlayerPrefs.SetInt(key, value ? 1 : 0);\r\n    }\r\n    public static void SaveInt(string key, int value) {\r\n        PlayerPrefs.SetInt(key, value);\r\n    }\r\n}\r\n\r\npublic class SkillTree : MonoBehaviour {\r\n    [Header(\"UI\")]\r\n    public Player player;\r\n    public GameObject linesContainer;\r\n    public GameObject line;\r\n    public GameObject confirmationPane;\r\n    public GameObject confirmationModal;\r\n    public TMP_Text skillPointCountText;\r\n    public TMP_Text confirmationTitle;\r\n    public TMP_Text confirmationSkillName;\r\n    public TMP_Text confirmationSkillCost;\r\n    public Button confirmationBuyButton;\r\n    public Color limeGreen;\r\n\r\n    ////////\r\n    // STATE\r\n    ////////\r\n    [Header(\"State\")]\r\n    public bool execInEditor;\r\n    public int skillPointCount = initPointCount;\r\n    const int initPointCount = 999;\r\n    static List<Skill> skills = new();\r\n    List<GameObject> lines = new();\r\n    List<string> skillNames;\r\n    Skill selectedSkill;\r\n\r\n    /////////\r\n    // PUBLIC\r\n    /////////\r\n    public static bool Has(string skillName) {\r\n        return skills.Where(s => s.name.ToLower() == skillName.ToLower() && s.purchased).Count() > 0;\r\n    }\r\n    public void ShowConfirmation(Skill s) {\r\n        selectedSkill = s;\r\n        \r\n        confirmationTitle.text = $\"Buy <b>[{s.name}]</b> for ${s.cost}?\";\r\n        confirmationSkillName.text = s.name;\r\n        confirmationSkillCost.text = $\" ${s.cost}\";\r\n        confirmationBuyButton.interactable = skillPointCount >= s.cost;\r\n        confirmationBuyButton.GetComponent<Image>().color = confirmationBuyButton.interactable ? limeGreen : Color.white;\r\n        confirmationBuyButton.GetComponentInChildren<TMP_Text>().color = confirmationBuyButton.interactable ? Color.black : Color.black.a(0.5f);\r\n        confirmationPane.SetActive(true);\r\n        confirmationModal.SetActive(true);\r\n    }\r\n    public void BuySkill() {\r\n        if (skillPointCount < selectedSkill.cost || selectedSkill == null)\r\n            return;\r\n        \r\n        selectedSkill.Purchase();\r\n        skillPointCount -= selectedSkill.cost;\r\n        ES3.SaveInt(\"skillPointCount\", skillPointCount);\r\n\r\n        selectedSkill = null;\r\n        UpdateTree();\r\n        HideConfirmation();\r\n    }\r\n    public void HideConfirmation() {\r\n        confirmationPane.SetActive(false);\r\n        confirmationModal.SetActive(false);\r\n    }\r\n    public void Reset() {\r\n        skills.ForEach(s => s.Reset());\r\n\r\n        ES3.SaveInt(\"skillPointCount\", initPointCount);\r\n        skillPointCount = initPointCount;\r\n\r\n        UpdateTree();\r\n        player.Awake();\r\n    }\r\n\r\n    ////////////\r\n    // UTILITIES\r\n    ////////////\r\n    static Color GetSkillColor(Skill s) {\r\n        if (s.purchased)\r\n            return Color.green;\r\n        if (s.unlocked)\r\n            return Color.white;\r\n        return Color.gray;\r\n    }\r\n    static List<Skill> GetRootSkills() {\r\n        return skills.Where(s0 => skills.All(s1 => !s1.next.Contains(s0))).ToList();\r\n    }\r\n    void DrawLine(Skill s0, Skill s1) {\r\n        // make line\r\n        GameObject l = Instantiate(line);\r\n        l.transform.SetParent(linesContainer.transform);\r\n        l.SetActive(true);\r\n        l.name = $\"{s0.name} -> {s1.name}\";\r\n        lines.Add(l);\r\n\r\n        // set positions\r\n        LineRenderer lr = l.GetComponent<LineRenderer>();\r\n        lr.SetPosition(0, s0.gameObject.transform.position);\r\n        lr.SetPosition(1, s1.gameObject.transform.position);\r\n\r\n        // set line colors\r\n        lr.startColor = GetSkillColor(s0);\r\n        lr.endColor = GetSkillColor(s1);\r\n    }\r\n    void DestroyLines() {\r\n        lines.ForEach(l => DestroyImmediate(l));\r\n        for (int i = linesContainer.transform.childCount-1; i >= 0; i--)\r\n            DestroyImmediate(linesContainer.transform.GetChild(i).gameObject);\r\n        lines.Clear();\r\n    }\r\n    void UpdateTree() {\r\n        // skill points\r\n        skillPointCountText.text = $\"${skillPointCount}\";\r\n\r\n        // destroy existing lines\r\n        DestroyLines();\r\n\r\n        // draw lines between skills\r\n        skills.ForEach(s0 => {\r\n            s0.next.ForEach(s1 => {\r\n                DrawLine(s0, s1);\r\n            });\r\n        });\r\n\r\n        // enable root nodes\r\n        List<Skill> roots = GetRootSkills();\r\n        skills.ForEach(s => s.Enable(false));\r\n        roots.ForEach(s => s.Enable(true));\r\n\r\n        // enable all children of purchased nodes\r\n        skills.ForEach(s0 => {\r\n            if (s0.purchased)\r\n                s0.next.ForEach(s1 => s1.Enable(true));\r\n        });\r\n    }\r\n\r\n    ///////////////\r\n    // UNITY EVENTS\r\n    ///////////////\r\n    void Awake() {\r\n        // get all skills\r\n        gameObject.GetComponentsInChildren<Skill>(skills);\r\n\r\n        // reset lines\r\n        DestroyLines();\r\n\r\n        // reset on first load\r\n        if (!ES3.LoadBool(\"loaded\", false)) {\r\n            ES3.SaveInt(\"skillPointCount\", initPointCount);\r\n            skills.ForEach(s => s.Reset());\r\n            ES3.SaveBool(\"loaded\", true);\r\n        }\r\n        \r\n        // load skill point count\r\n        skillPointCount = ES3.LoadInt(\"skillPointCount\", skillPointCount);\r\n\r\n        UpdateTree();\r\n        player.Awake();\r\n    }\r\n    void Start() {\r\n        UpdateTree();\r\n    }\r\n}";